function makeActor(kind='player',variant=0){const root=new THREE.Group(),pose=new THREE.Group();root.add(pose);const isPlayer=kind==='player';const skin=isPlayer?M.skin:[M.zskin,M.zskin2,M.zskin3][variant%3],top=isPlayer?M.player:(variant===1?M.red:M.dark),pants=isPlayer?M.pants:M.dark;
