const limbs=[];for(let side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.2,.87,0);pose.add(leg);box(leg,0,-.36,0,.24,.73,.27,pants);box(leg,0,-.73,.09,.28,.17,.42,M.dark);limbs.push(leg);const arm=new THREE.Group();arm.position.set(side*.43,1.49,0);pose.add(arm);box(arm,0,-.31,0,.21,.65,.22,top);mesh(sphereGeo,skin,arm,0,-.63,.02,.13,.15,.13);limbs.push(arm)}
if(isPlayer){box(pose,0,1.25,-.27,.55,.68,.22,M.pack);const gun=new THREE.Group();gun.position.set(.5,.91,.35);pose.add(gun);box(gun,0,.04,.16,.13,.13,.58,M.steel);box(gun,0,-.06,.02,.12,.19,.2,M.dark);box(gun,0,-.2,.04,.09,.22,.11,M.dark);root.userData.gun=gun}
if(!isPlayer){box(pose,-.24,1.47,.05,.18,.13,.2,M.blood);if(variant===1){box(pose,0,1.22,-.28,.76,.74,.34,top)}}
root.add(new THREE.AxesHelper(0));root.userData={pose,limbs,variant,phase:Math.random()*6};return root}
const player=makeActor('player');scene.add(player);player.position.set(0,0,0);const playerState={health:100,stamina:100,ammo:12,reserve:48,weapon:0,loot:0,shots:0,kills:0,dead:false,attackAt:0,dodgeUntil:0,invulnUntil:0,reloadUntil:0,step:0};
const zombieDefs=[{name:'SHAMBLER',hp:65,speed:1.28,damage:10,color:0x78816f},{name:'RUNNER',hp:45,speed:2.55,damage:8,color:0x987367},{name:'BRUTE',hp:150,speed:.83,damage:20,color:0x667364}];const zombies=[];
