function flash(){const f=$('#hitflash');f.style.opacity='.8';setTimeout(()=>f.style.opacity='0',180)}
function updateHUD(){let s=playerState;$('#healthBar').style.width=s.health+'%';$('#healthNum').textContent=Math.ceil(s.health);$('#staminaBar').style.width=s.stamina+'%';$('#staminaNum').textContent=Math.ceil(s.stamina);$('#ammoNow').textContent=s.ammo;$('#ammoReserve').textContent=s.reserve;$('#weaponName').textContent=s.weapon?'HUNTING KNIFE':'SERVICE PISTOL';$('#attackLabel').textContent=s.weapon?'STRIKE':'FIRE';$('#threatCount').textContent=zombies.filter(z=>!z.dead).length.toString().padStart(2,'0');$('#lootCount').textContent=s.loot;if(s.loot>=3){$('#objective').textContent='REACH EXTRACTION';$('#objectiveSub').innerHTML='Move to the green flare<br>Supplies secured 3 / 3'} }
function setWeapon(){playerState.weapon=1-playerState.weapon;$('#attackLabel').textContent=playerState.weapon?'STRIKE':'FIRE';$('#weaponName').textContent=playerState.weapon?'HUNTING KNIFE':'SERVICE PISTOL';notify(playerState.weapon?'KNIFE EQUIPPED':'PISTOL EQUIPPED')}
function reload(){let s=playerState;if(s.weapon||s.ammo===12||s.reserve<=0||s.reloadUntil>elapsed)return;s.reloadUntil=elapsed+1.25;notify('RELOADING…');setTimeout(()=>{if(playerState.dead)return;let n=Math.min(12-playerState.ammo,playerState.reserve);playerState.ammo+=n;playerState.reserve-=n;updateHUD()},1250)}

